const STAGES=[
 {id:'ironforge',name:'Ironforge & Kharanos',short:'Ironforge',sub:'Begin the royal chain · Pick up Hurley',travel:'City preparation',intro:'Use Ironforge as your starting anchor. Keep your hearth set to Stormwind; its useful moment comes after Lakeshire.',steps:[
  {id:'prepare',title:'Make room and keep your Stormwind hearth',tag:'Prepare',text:'Reach <strong>Ironforge</strong>. Repair, empty bags and make room for nine BRD objectives plus temporary prerequisites. Keep several quest slots free for the prison follow-ups. If already in Stormwind, use the <strong>Deeprun Tram</strong> in the Dwarven District.',note:'Your known flight paths: Ironforge, Stormwind, Thorium Point and Morgan’s Vigil. Lakeshire’s flight path is picked up on this route if needed.'},
  {id:'historian-story',title:'Listen to the royal historian',tag:'Min 50',text:'At the <strong>High Seat, Ironforge ~38.4, 55.3</strong>, accept <strong>The Smoldering Ruins of Thaurissan</strong> from <strong>Royal Historian Archesonus</strong>. Finish her conversation and turn in this first, dialogue-only quest.',sources:[Q(3702,'Historian’s opening quest')]},
  {id:'historian-relic',title:'Accept the relic-collection follow-up',tag:'Accept',text:'Speak to Archesonus again. Accept the second <strong>The Smoldering Ruins of Thaurissan</strong>, the version requiring <strong>12 pieces of information</strong> from relics in the Burning Steppes. Magni’s prisoner quest is unlocked after this return.',sources:[Q(3701,'Relic quest')]},
  {id:'hurley',title:'Pick up Hurley Blackbreath in Kharanos',tag:'Min 50',text:'Ride south out of Ironforge to <strong>Ragnar Thunderbrew</strong> in the <strong>Thunderbrew Distillery, Kharanos, Dun Morogh ~46.8, 52.4</strong>. Accept <strong>Hurley Blackbreath</strong>. Return to Ironforge’s flight master.',note:'No Blasted Lands trip needed. The “Ragnar Thunderbrew” delivery from Nethergarde is an optional breadcrumb, not a prerequisite. Literal breadcrumb completists should see Optional & later before accepting.',sources:[Q(4126,'Hurley Blackbreath'),SOURCES.tavern]}
 ]},
 {id:'steppes',name:'Morgan’s Vigil & the field loop',short:'Burning Steppes',sub:'Three pickups · Dragons · Relics · Pyron',travel:'Eastern loop, then the mountain',intro:'Fly Ironforge → Morgan’s Vigil. Take the local quests before killing anything. The dragon and Pyron portions include elites; arrange help at level 53.',steps:[
  {id:'dragonkin-pickup',title:'Accept Dragonkin Menace',tag:'Prerequisite',text:'At <strong>Morgan’s Vigil</strong>, speak to <strong>Helendis Riverhorn ~85.6, 69.0</strong>. Accept <strong>Dragonkin Menace</strong>, the opening of Windsor’s chain.',sources:[Q(4182,'Dragonkin Menace')]},
  {id:'pyron-pickup',title:'Accept Overmaster Pyron',tag:'Prerequisite',text:'Speak to <strong>Jalinda Sprig ~85.4, 70.1</strong>. Accept <strong>Overmaster Pyron</strong>. This unlocks <strong>Incendius!</strong>; Pyron is outside the dungeon portal.',sources:[Q(4262,'Overmaster Pyron')]},
  {id:'good-stuff',title:'Accept The Good Stuff',tag:'Min 50',text:'Speak to <strong>Oralius ~84.6, 68.7</strong> in the same camp. Accept <strong>The Good Stuff</strong> for <strong>20 Dark Iron Fanny Packs</strong> from dwarves in BRD.',sources:[Q(4286,'The Good Stuff')]},
  {id:'dragonkin-kills',title:'Finish the eastern dragonkin objectives',tag:'Group helps',type:'group',text:'Hunt in the eastern Burning Steppes around the dragonkin areas. Complete <strong>15 Black Broodlings, 10 Black Dragonspawn, 4 Black Wyrmkin and 1 Black Drake</strong>. Check the counters before leaving the east side.',note:'At 53, plan help for the elite targets. Don’t substitute Cyrus’s special summoned drake for the named Black Drake objective unless your quest counter actually credits it.',sources:[Q(4182,'Kill requirements')]},
  {id:'cyrus-unlock',title:'Visit Cyrus and obtain proof',tag:'Group helps',type:'group',text:'Continue northeast to <strong>Cyrus Therepentous’s cave, ~95.0, 31.6</strong>. If you already have a <strong>Black Dragonflight Molt</strong>, show it to him. Otherwise accept his opening <strong>A Taste of Flame</strong>, speak again and use the challenge dialogue to summon a <strong>Frenzied Black Drake</strong>. Kill it with help, loot the Molt and complete the opening stage.',note:'Shortcut check: the database has alternate Molt prerequisites, but the summon walkthrough is inherited Classic evidence. Confirm Cyrus offers it in your live game. If he does not, expand the fallback in Optional & later; do not mark this complete.',warn:true,sources:[Q(4023,'Summoned-drake alternative'),Q(4022,'Existing-Molt alternative')]},
  {id:'taste',title:'Take the Bael’Gar version of A Taste of Flame',tag:'Min 52',text:'Finish Cyrus’s dialogue and accept the follow-up that explicitly says to kill <strong>Bael’Gar in Blackrock Depths</strong>. Keep the supplied <strong>Altered Black Dragonflight Molt</strong> in your bags. This is the actual dungeon objective, quest #4024.',sources:[Q(4024,'Bael’Gar quest')]},
  {id:'relics',title:'Collect 12 relic readings in Thaurissan',tag:'Field objective',text:'Work west through the <strong>Ruins of Thaurissan in northern Burning Steppes, roughly ~62, 34</strong>. Interact with <strong>Thaurissan Relics</strong> until the historian’s quest shows <strong>12/12</strong>. You will return these during the city messenger loop.',note:'Save Flame Crest’s NPC stop for the Ragged John leg. Picking up its two standalone quests now would not remove that later required visit.',sources:[Q(3701,'Thaurissan relic objective')]},
  {id:'pyron-kill',title:'Kill Pyron outside the BRD portal',tag:'Group helps',type:'group',text:'Head west into <strong>Blackrock Mountain</strong>. Descend via the great chains and central tomb to the lower quarry passage. Find <strong>Overmaster Pyron</strong> in <strong>Blackrock Depths’ approach / Blackrock Quarry</strong> and kill him. You do <strong>not</strong> zone into BRD for this quest.',note:'This early mountain visit earns Incendius before your actual dungeon run. If you cannot get help now, leave this step unchecked and do Pyron with your party later; the return to Jalinda is still required.',sources:[Q(4262,'Pyron prerequisite')]},
  {id:'ghost-key',title:'Get the actual Dark Iron Legacy objective',tag:'Min 48 · Ghost',text:'On this mountain visit, speak to <strong>Franclorn Forgewright</strong> in the <strong>central suspended tomb while you are a ghost</strong>. Finish the first <strong>Dark Iron Legacy</strong> conversation, then accept the second quest—the one requiring <strong>Ironfel from Fineous Darkvire</strong>. Recover your body afterward.',note:'Franclorn is outside the instance and is not visible while alive. Use normal corpse recovery; a spirit-healer resurrection is unnecessary. If playing any permanent-death ruleset, defer this step rather than deliberately dying.',sources:[Q(3801,'First conversation'),Q(3802,'Ironfel follow-up')]},
  {id:'incendius',title:'Return to Jalinda and accept Incendius!',tag:'Min 48',text:'Return to <strong>Morgan’s Vigil</strong>. Turn in <strong>Overmaster Pyron</strong> to <strong>Jalinda Sprig</strong> and accept <strong>Incendius!</strong>. Verify the new quest is in your log before leaving.',sources:[Q(4263,'Incendius!')]},
  {id:'true-masters-start',title:'Turn in Dragonkin Menace and start the messenger chain',tag:'Prerequisite',text:'At <strong>Helendis Riverhorn</strong>, turn in <strong>Dragonkin Menace</strong> and accept <strong>The True Masters</strong>, addressed to <strong>Magistrate Solomon in Lakeshire</strong>. Keep the completed relic quest for your Ironforge return.',sources:[Q(4183,'The True Masters: Solomon')]}
 ]},
 {id:'cities',name:'Lakeshire, Stormwind & Ironforge',short:'City loop',sub:'Use your hearth · Unlock Kharan',travel:'Lakeshire → Hearth → Tram',intro:'The Stormwind delivery is mandatory. Add the Ironforge relic turn-in immediately afterward so it does not become a separate expedition.',steps:[
  {id:'solomon-first',title:'Deliver to Solomon and learn Lakeshire’s flight path',tag:'Travel',type:'travel',text:'Ride south from the Burning Steppes through the pass into <strong>Redridge Mountains</strong>, then to <strong>Lakeshire</strong>. Learn the flight path if needed. At the town hall, <strong>Magistrate Solomon ~24.8, 44.2</strong> takes your message and gives the next <strong>The True Masters</strong> for Bolvar.',sources:[Q(4183,'Delivery to Solomon'),Q(4184,'Delivery to Bolvar')]},
  {id:'bolvar',title:'Hearth to Stormwind and report to Bolvar',tag:'Use hearth',type:'travel',text:'Use your <strong>Stormwind Hearthstone</strong>. If it is on cooldown, fly from Lakeshire instead of waiting. At <strong>Stormwind Keep</strong>, speak to <strong>Highlord Bolvar Fordragon ~80.0, 38.6</strong>, turn in the message and accept the next <strong>The True Masters</strong>.',sources:[Q(4184,'Bolvar delivery'),Q(4185,'Keep investigation')]},
  {id:'prestor',title:'Talk to Katrana, then return to Bolvar',tag:'Dialogue',text:'Speak to <strong>Lady Katrana Prestor</strong> nearby and finish the quest dialogue, even if she has no exclamation mark. Return to <strong>Bolvar</strong>, turn in, then accept <strong>The True Masters</strong> for Solomon. Keep <strong>Bolvar’s Decree</strong>.',sources:[Q(4185,'Katrana dialogue'),Q(4186,'Bolvar’s Decree')]},
  {id:'kharan',title:'Tram to Ironforge; unlock Kharan Mighthammer',tag:'Min 50',text:'Take the <strong>Deeprun Tram</strong> back to Ironforge. Turn in the <strong>12 relic readings</strong> to <strong>Royal Historian Archesonus</strong>. Speak to <strong>King Magni Bronzebeard ~39.1, 56.2</strong> beside her and accept <strong>Kharan Mighthammer</strong>.',note:'The Fate of the Kingdom is not available yet. First you must interview Kharan inside BRD and carry his news back to Magni.',sources:[Q(3701,'Relic turn-in'),Q(4341,'Kharan Mighthammer')]},
  {id:'solomon-second',title:'Fly back to Lakeshire with the decree',tag:'Travel',type:'travel',text:'Fly <strong>Ironforge → Lakeshire</strong>. Turn in <strong>The True Masters</strong> to <strong>Magistrate Solomon</strong>, then accept the next message, for <strong>Marshal Maxwell at Morgan’s Vigil</strong>.',sources:[Q(4186,'Return to Solomon'),Q(4223,'Message to Maxwell')]}
 ]},
 {id:'flamecrest',name:'Maxwell & the Flame Crest sweep',short:'Flame Crest',sub:'Ragged John · Two neutral pickups',travel:'Morgan’s Vigil → Flame Crest',intro:'This is the right time for Flame Crest: Ragged John’s story now advances your active chain, and both neutral quest givers are beside him.',steps:[
  {id:'maxwell-john',title:'Get Maxwell’s instruction to question Ragged John',tag:'Prerequisite',text:'Fly or ride north to <strong>Morgan’s Vigil</strong>. Give Solomon’s message to <strong>Marshal Maxwell ~84.6, 68.8</strong>. Accept the next <strong>The True Masters</strong>, which sends you to <strong>Ragged John</strong>.',sources:[Q(4223,'First Maxwell delivery'),Q(4224,'Ragged John stage')]},
  {id:'ragged-john',title:'Listen to Ragged John’s full story',tag:'Dialogue',text:'Ride northwest to <strong>Flame Crest</strong> in northern Burning Steppes. At <strong>Ragged John ~65.0, 23.6</strong>, work through his story until the quest objective is complete. He is the interview, not the final turn-in—Maxwell is waiting back at Morgan’s Vigil.',sources:[Q(4224,'The True Masters: interview')]},
  {id:'heart',title:'Accept The Heart of the Mountain',tag:'Min 50',text:'At <strong>Maxwort Uberglint ~65.2, 23.8</strong>, accept <strong>The Heart of the Mountain</strong>. The objective is in BRD’s <strong>Black Vault</strong>, not at a surface mountain landmark.',sources:[Q(4123,'The Heart of the Mountain')]},
  {id:'ribbly',title:'Accept Ribbly Screwspigot directly',tag:'Min 48',text:'At <strong>Yuka Screwspigot ~66.0, 22.0</strong>, accept <strong>Ribbly Screwspigot</strong>. Your target is in the <strong>Grim Guzzler</strong> inside BRD.',note:'Skip Tanaris for the efficient route. “Yuka Screwspigot” from Yorba in Steamwheedle Port is a breadcrumb, not required for Ribbly. Take that first only if you want the breadcrumb itself credited.',sources:[Q(4136,'Ribbly Screwspigot'),Q(4324,'Optional Yuka breadcrumb')]}
 ]},
 {id:'windsor',name:'Return to Maxwell',short:'Morgan’s Vigil',sub:'Unlock Marshal Windsor',travel:'One required return',intro:'Do not head straight from Flame Crest to the instance. This final turn-in is what actually gives you the prisoner quest.',steps:[
  {id:'windsor',title:'Accept Marshal Windsor',tag:'Min 48',text:'Return to <strong>Marshal Maxwell at Morgan’s Vigil</strong>. Turn in <strong>The True Masters</strong> after completing John’s story. Accept <strong>Marshal Windsor</strong> and check that it appears in your log.',sources:[Q(4241,'Marshal Windsor')]}
 ]},
 {id:'entrance',name:'The mountain & your first entry',short:'Blackrock Depths',sub:'Check nine objectives · Meet your party',travel:'Enter ready',intro:'Your prep is complete when the actual dungeon objectives are in your log—not merely their breadcrumbs.',steps:[
  {id:'entry-audit',title:'Confirm the nine entry objectives',tag:'Log check',text:'Verify <strong>Hurley Blackbreath; The Good Stuff; Incendius!; A Taste of Flame (Bael’Gar); The Heart of the Mountain; Ribbly Screwspigot; Kharan Mighthammer; Marshal Windsor; Dark Iron Legacy (Ironfel)</strong>. Use the Quest ledger to locate any missing prerequisite.',note:'Keep the Altered Black Dragonflight Molt in your bags. A missing quest should remain unchecked. This guide tracks your actions manually; it cannot read your game’s quest log.'},
  {id:'enter',title:'Meet your party at the BRD portal',tag:'Group run',type:'group',text:'From Morgan’s Vigil, ride west to <strong>Blackrock Mountain</strong>. Descend the chains past the central tomb into the lower quarry, then follow the passage to the <strong>BRD instance portal</strong>. Your Thorium Point flight path is a useful alternative when approaching from the north.',note:'Plan a prison-first quest run at level 53. You can enter the prison section without a Shadowforge Key. Emperor and the deeper objectives are tougher; completing everything in one level-53 outing is not assumed.'}
 ]}
];
