const EXTRA_LIBRARY=[
 {id:'love',name:'The Love Potion: outdoor ingredients',sub:'Available at 53 · Starts inside BRD',intro:'This is a real dungeon quest, included for completeness. It cannot be fully finished on your first entry from zero because Nagmara gives you the empty vial inside.',steps:[
  {id:'love-herbs',title:'Obtain 4 Gromsblood',tag:'Ingredient',text:'After accepting <strong>The Love Potion</strong>, gather or buy <strong>4 Gromsblood</strong>. These herbs can also be bought before the dungeon if you want to prepare.',sources:[Q(4201,'Ingredient list')]},
  {id:'love-giants',title:'Collect 10 Giant Silver Veins in Azshara',tag:'Group helps',type:'group',text:'With the quest active, kill <strong>Cliff Breakers, Cliff Thunderers or Cliff Walkers</strong> in <strong>Azshara</strong> for <strong>10 Giant Silver Veins</strong>. These are quest drops from giants, not mining nodes. Arrange help if needed.',sources:[Q(4201,'Giant drops')]},
  {id:'love-vial',title:'Fill Nagmara’s Vial in Un’Goro',tag:'Travel',type:'travel',text:'Take the empty <strong>Nagmara’s Vial</strong> to <strong>Golakka Hot Springs, Un’Goro Crater</strong>. Use it in the water at the top of the volcanic mound to obtain <strong>Nagmara’s Filled Vial</strong>. Batch this long trip with your Kalimdor questing when convenient.',sources:[Q(4201,'Vial objective')]},
  {id:'love-return',title:'Return all three ingredients to Nagmara',tag:'BRD return',text:'On a later BRD visit, bring <strong>4 Gromsblood, 10 Giant Silver Veins and the Filled Vial</strong> back to <strong>Mistress Nagmara in the Grim Guzzler</strong>. Complete <strong>The Love Potion</strong>.',sources:[Q(4201,'Love Potion turn-in')]}
 ]},
 {id:'mining',name:'The Spectral Chalice',sub:'Only if you have Mining 230+',intro:'Profession-dependent. You do not need this quest merely because you are a paladin. It teaches Dark Iron smelting.',steps:[
  {id:'mining-mats',title:'Bring the tribute if you qualify',tag:'Mining 230+',type:'optional',text:'Prepare <strong>2 Star Rubies, 20 Gold Bars and 10 Truesilver Bars</strong> before a deep run. The database minimum is level 40, but the meaningful gate is <strong>Mining 230</strong>.',sources:[Q(4083,'The Spectral Chalice')]},
  {id:'chalice',title:'Speak to Gloom’rel before the Seven fight',tag:'Before combat',text:'In the <strong>Summoners’ Tomb</strong>, speak to <strong>Gloom’rel</strong> about smelting, offer the materials through the <strong>Spectral Chalice</strong>, then speak to Gloom’rel again to learn. Do this <strong>before anyone starts the Seven encounter</strong>.',sources:[Q(4083,'Chalice tribute and dialogue')]}
 ]},
 {id:'breadcrumbs',name:'Literal completionists: optional breadcrumbs',sub:'Extra travel · Not needed to unlock the BRD objectives',intro:'The main route intentionally skips these two delivery quests. If “all” includes every breadcrumb completion, do these first; they can disappear after their destination quests are accepted or completed.',steps:[
  {id:'breadcrumb-ragnar',title:'Optional: Nethergarde → Kharanos',tag:'Extra detour',type:'optional',text:'Before taking Hurley, visit <strong>Enohar Thunderbrew at Nethergarde Keep, Blasted Lands</strong>. Accept <strong>Ragnar Thunderbrew</strong> (#4128, minimum 50), deliver it to Ragnar in <strong>Kharanos</strong>, then take Hurley. This adds travel but credits the breadcrumb itself.',sources:[Q(4128,'Ragnar Thunderbrew breadcrumb'),SOURCES.tavern]},
  {id:'breadcrumb-yuka',title:'Optional: Steamwheedle Port → Flame Crest',tag:'Extra detour',type:'optional',text:'Before taking Ribbly, visit <strong>Yorba Screwspigot at Steamwheedle Port, Tanaris ~67, 24</strong>. Accept <strong>Yuka Screwspigot</strong> (#4324, minimum 48), then deliver it to Yuka when the main route reaches <strong>Flame Crest</strong>.',sources:[Q(4324,'Yuka Screwspigot breadcrumb')]}
 ]},
 {id:'cyrus-fallback',name:'If Cyrus does not offer the short path',sub:'Conditional fallback · Do not do this automatically',intro:'Some current guides insist on the Searing Gorge chain; the quest records offer alternate prerequisites. Check the short route first. The sequence below is inherited Classic mechanics, not a live-tested Forever guarantee.',steps:[
  {id:'cyrus-long',title:'Obtain the Molt through the Searing Gorge chain',tag:'Fallback only',type:'optional',text:'At <strong>Kalaran Windblade in Searing Gorge ~39, 39</strong>, follow <strong>Divine Retribution → The Flawless Flame → Forging the Shaft → The Flame’s Casing → The Torch of Retribution</strong> (its successive stages) <strong>→ Squire Maltrake → Set Them Ablaze! → Trinkets…</strong>. Loot the <strong>Black Dragonflight Molt</strong> from the reward chest, then return to Cyrus for the Molt-proof version and the Bael’Gar quest.',note:'This is a long alternative with elite objectives. Verify the next quest is offered in your game; if a Forever change blocks both routes, keep A Taste of Flame pending instead of treating an old guide as confirmation.',sources:[Q(3441,'Divine Retribution'),Q(3463,'Set Them Ablaze!'),Q(3481,'Trinkets…'),Q(4022,'Molt proof')]}
 ]}
];
const LATER=[
 {name:'Attunement to the Core',gate:'55+ in inherited records; current availability disputed',detail:'Do not route to it at 53. Some Forever guides carry the Classic quest; a November report says Lothos / the quest is not live. Recheck in game when eligible. A database record is not proof that the quest can currently be accepted.',sources:[Q(7848,'Retained quest record'),SOURCES.core]},
 {name:'The Challenge',gate:'58+ and the long Dungeon Set 2 chain',detail:'Falrin Treeshaper in Dire Maul eventually sends you to summon Theldren in BRD’s Ring of Law. Not a standalone pickup for your current preparation.',sources:[Q(9015,'The Challenge')]},
 {name:'In Demand – Blackrock Legal Records',gate:'60; rotating weekly offer',detail:'Pix Xizzix in Booty Bay can ask for documents from Emperor Thaurissan, Overlord Wyrmthalak and General Drakkisath. Includes both BRD and Blackrock Spire; confirm the current weekly offer at 60.',sources:[SOURCES.weekly]},
 {name:'A Binding Contract',gate:'60; Sulfuron Ingot / raid material access',detail:'Lokhtos Darkbargainer in the Grim Guzzler exchanges a Sulfuron Ingot through the contract sequence for the Sulfuron Hammer plan. Conditional on access to the required material and live content.',sources:[Q(7604,'A Binding Contract')]},
 {name:'Morndeep the Elder',gate:'Lunar Festival only, if offered in Forever',detail:'A seasonal visit inside the Ring of Law. It is not a normal November pickup; verify the event’s live availability rather than treating a retained seasonal record as active.',sources:[Q(8619,'Morndeep the Elder')]}
];
